function createTracker(name, initialLessons = []) {
  // TODO: return tracker object
  return { name, lessons: initialLessons };
}

function addLesson(tracker, lesson) {
  // TODO: push lesson and return tracker
  tracker.lessons.push(lesson);
  return tracker;
}

function countCompleted(tracker) {
  // TODO: return count of completed lessons
  return tracker.lessons.filter(l => l.completed).length;
}

function calculateProgressPercentage(tracker) {
  // TODO: calculate rounded percentage (0 if lessons is empty)
  if (!tracker.lessons.length) return 0;
  const completed = countCompleted(tracker);
  return Math.round((completed / tracker.lessons.length) * 100);
}

function getIncompleteLessons(tracker) {
  // TODO: return array of lesson titles where completed is false
  return tracker.lessons.filter(l => !l.completed).map(l => l.title);
}

function generateLearnerSummary(tracker) {
  // TODO: return formatted summary string
  const pct = calculateProgressPercentage(tracker);
  const done = countCompleted(tracker);
  const total = tracker.lessons.length;
  const remaining = getIncompleteLessons(tracker);
  const remainingText = remaining.length > 0 ? remaining.join(', ') : 'None';
  return `${tracker.name} — ${pct}% complete (${done}/${total} lessons). Remaining: ${remainingText}`;
}
